import { acNameToEmojiMap } from './acNameToEmojiMap';
import { DEFAULT_EMOJI_ID } from './emoji';
export function acNameToEmoji(acName) {
  const emojiData = acNameToEmojiMap[acName];
  return emojiData ? {
    id: emojiData[0],
    shortName: emojiData[1],
    text: emojiData[2]
  } : {
    id: DEFAULT_EMOJI_ID,
    shortName: `:${acName}:`,
    text: ''
  };
}